def rect_perims(din, dout, blocks, rr, cc):
    # blocks: dict color -> list of (bi,bj); edges as gap-paint per line index
    # verify by painting: for each color forming a rectangle, paint perimeter edges
    H=len(din); W=len(din[0])
    rg=groups([any(v!=0 for v in r) for r in din]); cg=groups([any(din[r][c]!=0 for r in range(H)) for c in range(W)])
    rgp={i+1:(rg[i][1]+1, rg[i+1][0]-1) for i in range(len(rg)-1)}
    cgp={i+1:(cg[i][1]+1, cg[i+1][0]-1) for i in range(len(cg)-1)}
    out=[r[:] for r in din]
    bh = blocks.get('bh')  # block height/width in cells
    bh = bh if bh else 1
    for color, pos in blocks['pos'].items():
        rs=sorted(set(p[0] for p in pos)); cs=sorted(set(p[1] for p in pos))
        if len(pos)!=len(rs)*len(cs): continue  # not full rectangle
        if len(rs)<2 or len(cs)<2: continue
        # top/bottom edges: block rows rs[0], rs[-1], gap cols between cs[0]..cs[-1]
        for bi in (rs[0], rs[-1]):
            r0=rr[bi]-(bh-1)//2; r1=rr[bi]+bh//2
            for k in range(cs[0]+1, cs[-1]+1):
                a,b=cgp[k]
                for r in range(r0,r1+1):
                    for c in range(a,b+1): out[r][c]=color
        for bj in (cs[0], cs[-1]):
            c0=cc[bj]-(bh-1)//2; c1=cc[bj]+bh//2
            for k in range(rs[0]+1, rs[-1]+1):
                a,b=rgp[k]
                for r in range(a,b+1):
                    for c in range(c0,c1+1): out[r][c]=color
    diff=[(r,c,out[r][c],dout[r][c]) for r in range(H) for c in range(W) if out[r][c]!=dout[r][c]]
    return len(diff), diff[:6]
