def find_dots(g):
    """uniform square blocks: for each cell, if same color solid kxk square and maximal; returns list (r,c,k,color)"""
    h,w=len(g),len(g[0])
    seen=set(); dots=[]
    def solid(r,c,k,col):
        if r+k>h or c+k>w: return False
        return all(g[i][j]==col for i in range(r,r+k) for j in range(c,c+k))
    for r in range(h):
        for c in range(w):
            col=g[r][c]
            if col==0 or (r,c) in seen: continue
            # max solid square size at r,c
            k=1
            while solid(r,c,k+1,col): k+=1
            if k>=2 and solid(r,c,k,col):
                # check maximality: not part of bigger square starting elsewhere -> mark cells
                for i in range(r,r+k):
                    for j in range(c,c+k): seen.add((i,j))
                dots.append((r,c,k,col))
            else:
                seen.add((r,c))
    return dots
