def extract_dots(g):
    """Return list of (r,c,size,color) for dots: inner uniform region of box frames, or solid blocks."""
    h,w=len(g),len(g[0])
    visited=[[False]*w for _ in range(h)]
    dots=[]
    # detect box frames: square of uniform border color c, size k>=3, perimeter all c
    for r in range(h):
        for c in range(w):
            col=g[r][c]
            if col==0 or visited[r][c]: continue
            # max square frame at r,c
            best=None
            for k in range(2,min(h-r,w-c)+1):
                per=all(g[r+i][c]==col and g[r+i][c+k-1]==col and g[r][c+j]==col and g[r+k-1][c+j]==col
                        for i in range(k) for j in range(k))
                if not per: break
                best=k
            if best and best>=3:
                inner=g[r+1][c+1]
                # uniform interior?
                if all(g[r+i][c+j]==inner for i in range(1,best-1) for j in range(1,best-1)) and inner!=col:
                    k=best-2
                    dots.append((r+1,c+1,k,inner))
                    for i in range(r,r+best):
                        for j in range(c,c+best): visited[i][j]=True
                    continue
    # solid blocks not inside frames
    for r in range(h):
        for c in range(w):
            col=g[r][c]
            if col==0 or visited[r][c]: continue
            k=1
            while r+k<h and c+k<w and all(g[i][j]==col for i in range(r,r+k+1) for j in range(c,c+k+1)): k+=1
            if k>=2:
                dots.append((r,c,k,col))
            for i in range(r,r+max(k,1)):
                for j in range(c,c+max(k,1)):
                    if i<h and j<w: visited[i][j]=True
    return dots

def line_pick(vals):
    pos={}
    for i,v in enumerate(vals): pos.setdefault(v,[]).append(i)
    cands=[(abs(p[1]-p[0]),v,p) for v,p in pos.items() if len(p)==2]
    if not cands: return None
    if len(cands)>1:
        m=min(c[0] for c in cands); best=[c for c in cands if c[0]==m]
        if len(best)>1: return None
        return best[0]
    return cands[0]

